    (@kanji_welcome, get_field_id('title'), '0000000002', 'Kanji Lernaufgabe'),
    (@kanji_welcome, get_field_id('label'), '0000000003', 'Kanji Learning Task'),
    (@kanji_welcome, get_field_id('title'), '0000000003', 'Kanji Learning Task');

