-- -----------------------------------------------------------------------
-- A finished code is not run twice
--
-- This is the first page after the code is typed, so it is the earliest
-- point the code is known, and nothing of the task has been written yet.
--
-- Both containers read the same row through data_config, filtered by the
-- code in the URL, and test `triggerType` from opposite sides. It is
-- `finished` only once the component saved with that trigger, so it means
-- the run reached the end — an abandoned run leaves it unset and can be
-- resumed, which is what the study wants.
--
-- `current_user` is false: participants are not logged in, so the row
-- belongs to the guest user rather than to whoever is visiting.
-- -----------------------------------------------------------------------

INSERT IGNORE INTO `sections` (`id_styles`, `name`, `owner`)
    VALUES (get_style_id('conditionalContainer'), 'kanji-task-1-open', NULL);
SET @kt1_open = (SELECT id FROM sections WHERE name = 'kanji-task-1-open');

INSERT INTO `sections_fields_translation` (`id_sections`, `id_fields`, `id_languages`, `id_genders`, `content`)
VALUES
    (@kt1_open, get_field_id('data_config'), '0000000001', '0000000001', '[{"table": "Kanji_Task1", "retrieve": "first", "current_user": false, "all_fields": false, "filter": "AND extra_param_code = ''{{__code__}}''", "fields": [{"field_name": "triggerType", "field_holder": "@page_state", "not_found_text": "none"}]}]'),
    (@kt1_open, get_field_id('condition'),   '0000000001', '0000000001', '{"and":[{"!=":["@page_state","finished"]}]}')
ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);

INSERT IGNORE INTO `sections` (`id_styles`, `name`, `owner`)
    VALUES (get_style_id('conditionalContainer'), 'kanji-task-1-done', NULL);
SET @kt1_done = (SELECT id FROM sections WHERE name = 'kanji-task-1-done');

INSERT INTO `sections_fields_translation` (`id_sections`, `id_fields`, `id_languages`, `id_genders`, `content`)
VALUES
    (@kt1_done, get_field_id('data_config'), '0000000001', '0000000001', '[{"table": "Kanji_Task1", "retrieve": "first", "current_user": false, "all_fields": false, "filter": "AND extra_param_code = ''{{__code__}}''", "fields": [{"field_name": "triggerType", "field_holder": "@page_state", "not_found_text": "none"}]}]'),
    (@kt1_done, get_field_id('condition'),   '0000000001', '0000000001', '{"and":[{"==":["@page_state","finished"]}]}')
ON DUPLICATE KEY UPDATE `content` = VALUES(`content`);

INSERT IGNORE INTO `sections` (`id_styles`, `name`, `owner`)
    VALUES (get_style_id('markdown'), 'kanji-task-1-done-text', NULL);
SET @kt1_done_text = (SELECT id FROM sections WHERE name = 'kanji-task-1-done-text');

INSERT INTO `sections_fields_translation` (`id_sections`, `id_fields`, `id_languages`, `id_genders`, `content`)
VALUES
    (@kt1_done_text, get_field_id('text_md'), (SELECT id FROM languages WHERE locale = 'de-CH'), '0000000001', '<div class="col-md-8 col-lg-6 mx-auto py-5 text-center"><p class="display-4 text-success mb-3">&#10003;</p><p class="small text-uppercase text-muted mb-2">Geschafft</p><h1 class="h3 mb-3">Diese Aufgabe wurde bereits abgeschlossen</h1><p class="lead mb-4">Unter Ihrem Code wurde die Aufgabe bereits vollständig bearbeitet. Vielen Dank für Ihre Teilnahme — sie ist nur einmal möglich.</p><p class="small text-muted mb-0">Sollte das nicht stimmen, wenden Sie sich bitte an das Studienteam.</p></div>'),
    (@kt1_done_text, get_field_id('text_md'), (SELECT id FROM languages WHERE locale = 'en-GB'), '0000000001', '<div class="col-md-8 col-lg-6 mx-auto py-5 text-center"><p class="display-4 text-success mb-3">&#10003;</p><p class="small text-uppercase text-muted mb-2">All done</p><h1 class="h3 mb-3">This task has already been completed</h1><p class="lead mb-4">The task has already been completed in full under your code. Thank you for taking part — it can only be done once.</p><p class="small text-muted mb-0">If you think this is not correct, please contact the study team.</p></div>'),
    (@kt1_done_text, get_field_id('text_md'), (SELECT id FROM languages WHERE locale = 'fr-CH'), '0000000001', '<div class="col-md-8 col-lg-6 mx-auto py-5 text-center"><p class="display-4 text-success mb-3">&#10003;</p><p class="small text-uppercase text-muted mb-2">Terminé</p><h1 class="h3 mb-3">Cette tâche a déjà été effectuée</h1><p class="lead mb-4">La tâche a déjà été entièrement effectuée avec votre code. Merci de votre participation — elle ne peut être réalisée qu’une seule fois.</p><p class="small text-muted mb-0">Si vous pensez que ce n’est pas correct, veuillez contacter l’équipe de l’étude.</p></div>'),
