alue":"6"},{"text":{"en":"University of applied sciences (FH), teacher training college (PH)","fr":"Haute école spécialisée (HES), haute école pédagogique (PH)","it":"Scuola universitaria professionale (SUP), scuola universitaria di pedagogiga (SUP)","default":"Fachhochschule (FH), Pädagogische Hochschule (PH)"},"value":"7"},{"text":{"en":"University (Uni, ETH)","fr":"Univeristé (Uni, ETH)","it":"Università (Uni, ETH)","default":"Universitäre Hochschule (Uni, ETH)"},"value":"8"}],"isRequired":true},{"name":"Demo_22","type":"radiogroup","title":{"en":"How much does the second parent work on average per week?","fr":"Combien le deuxième parent travaille-t-il en moyenne par semaine?","it":"Quante ore lavora in media alla settimana il secondo genitore?","default":"Wie viel arbeitet das zweite Elternteil/Erziehungsberechtiger durchschnittlich pro Woche?"},"choices":[{"text":{"en":"0%","fr":"0%","it":"0%","default":"0%"},"value":"7"},{"text":{"en":"Up to 20%","fr":"jusqu’à 20 %","it":"Fino al 20%","default":"bis 20%"},"value":"1"},{"text":{"en":"21-40%","fr":"21-40%","it":"21-40%","default":"21-40%"},"value":"2"},{"text":{"en":"41-60%","fr":"41-60%","it":"41-60%","default":"41-60%"},"value":"3"},{"text":{"en":"61-80%","fr":"61-80%","it":"61-80%","default":"61-80%"},"value":"4"},{"text":{"en":"81-100%","fr":"81-100%","it":"81-100%","default":"81-100%"},"value":"5"}],"colCount":0,"isRequired":true},{"name":"Demo_23","type":"text","title":{"en":"What is the current occupation of the other parent?","fr":"Quelle est la profession du deuxième parent?","it":"Qual è la professione del secondo genitore?","default":"Welchen Beruf hat das zweite Elternteil/Erziehungsberechtigter?"},"isRequired":true,"validators":[{"text":{"en":"Please do not enter numbers.","fr":"Veuillez ne pas saisir de chiffres.","it":"Non inserire numeri.","default":"Bitte geben Sie keine Zahlen ein."},"type":"regexvalidator","regex":"^(?=.*[A-Za-zÀ-ÿ])[^0-9]+$"}],"visibleIf":"{Demo_22} <> \'7\'"},{"name":"Demo_24","type":"checkbox","title":{"en":"What language(s) does the other parent speak? (Multiple answers possible)","fr":"Quelle(s) langue(s) le deuxième parent parle-t-il? (Plusieurs réponses possibles)","it":"Quale/i lingua/e parla il secondo genitore? (Sono possibili più risposte)","default":"Welche Sprache(n) spricht das zweite Elternteil/Erziehungsberechtigter? (Mehrere Antworten möglich)"},"choices":[{"text":{"en":"Swiss German","fr":"Suisse allemand","it":"Svizzero Tedesco","default":"Schweizerdeutsch"},"value":"37"},{"text":{"en":"German","fr":"Allemand","it":"Tedesco","default":"Deutsch"},"value":"1"},{"text":{"en":"Albanian","fr":"Albanais","it":"Albanese","default":"Albanisch"},"value":"16"},{"text":{"en":"Arabic","fr":"Arabe","it":"Arabo","default":"Arabisch"},"value":"19"},{"text":{"en":"English","fr":"Anglais","it":"Inglese","default":"Englisch"},"value":"20"},{"text":{"en":"Finnish","fr":"Finnois","it":"Finlandese","default":"Finnisch"},"value":"26"},{"text":{"en":"French","fr":"Français","it":"Francese","default":"Französisch"},"value":"2"},{"text":{"en":"Italian","fr":"Italien","it":"Italiano","default":"Italienisch"},"value":"3"},{"text":{"en":"Croatian","fr":"Croate","it":"Croato","default":"Kroatisch"},"value":"28"},{"text":{"en":"Kurdish","fr":"Kurde","it":"Curdo","default":"Kurdisch"},"value":"18"},{"text":{"en":"Macedonian","fr":"Macédonien","it":"Macedone","default":"Mazedonisch"},"value":"21"},{"text":{"en":"Dutch","fr":"Néerlandais","it":"Olandese","default":"Niederländisch"},"value":"27"},{"text":{"en":"Norwegian","fr":"Norvégien","it":"Norvegese","default":"Norwegisch"},"value":"33"},{"text":{"en":"Persian","fr":"Persan","it":"Persiano","default":"Persisch"},"value":"24"},{"text":{"en":"Portuguese","fr":"Portugais","it":"Portoghese","default":"Portugiesisch"},"value":"29"},{"text":{"en":"Romansh","fr":"Romanche","it":"Romancio","default":"Romanisch"},"value":"4"},{"text":{"en":"Russian","fr":"Russe","it":"Russo","default":"Russisch"},"value":"22"},{"text":{"en":"Swedish","fr":"Suédois","it":"Svedese","default":"Schwedisch"},"value":"32"},{"text":{"en":"Serbian","fr":"Serbe","it":"Serbo","default":"Serbisch"},"value":"31"},{"text":{"en":"Spanish","fr":"Espagnol","it":"Spagnolo","default":"Spanisch"},"value":"30"},{"text":{"en":"Tamil","fr":"Tamoul","it":"Tamil","default":"Tamil"},"value":"36"},{"text":{"en":"Thai","fr":"Thaïlandais","it":"Thailandese","default":"Thailändisch"},"value":"34"},{"text":{"en":"Tigrinya","fr":"Tigrinya","it":"Tigrino","default":"Tigrinya"},"value":"35"},{"text":{"en":"Turkish","fr":"Turc","it":"Turco","default":"Türkisch"},"value":"17"},{"text":{"en":"Hungarian","fr":"Hongrois","it":"Ungherese","default":"Ungarisch"},"value":"25"},{"text":{"en":"Ukrainian","fr":"Ukrainien","it":"Ucraino","default":"Ukrainisch"},"value":"23"},{"text":{"en":"Other (please specify):","fr":"Autre, à savoir (veuillez remplir le champ de texte suivant) :","it":"Altro, cioè (per favore compili il campo seguente):","default":"Andere, und zwar (bitte das folgende Textfeld ausfüllen):"},"value":"5"}],"isRequired":true},{"name":"Demo_24_other","type":"text","title":{"en":"Other language","fr":"Autre langue","it":"Altra lingua","default":"Andere Sprache"},"visibleIf":"{Demo_24} contains \'5\'","isRequired":true,"validators":[{"text":{"en":"Please do not enter numbers.","fr":"Veuillez ne pas saisir de chiffres.","it":"Non inserire numeri.","default":"Bitte geben Sie keine Zahlen ein."},"type":"regexvalidator","regex":"^(?=.*[A-Za-zÀ-ÿ])[^0-9]+$"}]}],"visibleIf":"{Demo_19} = \'1\'"}],"title":{"en":"Kanji – Part 2: Demographics","fr":"Kanji – Partie 2: données","it":"Kanji – Parte 2: dati","default":"Kanji – Teil 2: Angaben"},"locale":"de","completedHtml":{"en":"","fr":"","it":"","default":""},"checkErrorsMode":"onValueChanged","showProgressBar":"off","showQuestionNumbers":"off","showPrevButton":false,"pageNextText":{"en":"Continue","fr":"Continuer","it":"Continua","default":"Weiter"},"completeText":{"en":"Continue","fr":"Continuer","it":"Continua","default":"Weiter"},"theme":{"cssVariables":{"--sjs2-typography-font-size-component-question-title":"20px","--sjs2-typography-font-size-component-label-content":"16px","--sjs2-color-utility-body":"#eff8f5"}},"showTitle":false,"requiredText":"*"}';
