lPath":"CJ_unsicher_FR.png","poolPath":"embedded/f830ecb7e3d66166fdabbcf922aecdaf6a9013d5c3009777a98c88f3082486bb.jpg"},{"localPath":"CJ_mittel_FR.png","poolPath":"embedded/a2392a8c339f430652a2d0c93dc4607694907a5cf60f4a215d1a1f9a07549ae1.jpg"},{"localPath":"CJ_sicher_FR.png","poolPath":"embedded/3a406aac2f272fcdef0d5fa19c73f5a830f8bdfc3edc4261c094290f840a770f.jpg"},{"localPath":"CJ_unsicher_IT.png","poolPath":"embedded/61ba766c15eee965b8a275d35be75790882b85f1ba49a181032f5ada792112a0.jpg"},{"localPath":"CJ_mittel_IT.png","poolPath":"embedded/a9676f4d174d2f676fe6c195a4be48fc1528e6b17f92b1739472813cee48b9c1.jpg"},{"localPath":"CJ_sicher_IT.png","poolPath":"embedded/8203f55f4a9138d9d9ceed4dee13c2e9f7012b28ead7a9911e4f358df5e807fe.jpg"}],"responses":[],"messageHandlers":[{"message":"run","code":"const screen = this;\\nconst el = this.options.el;\\nconst pageStart = performance.now();\\nconst lang = (window.KANJI_LANG || (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\').match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'de\');\\nconst sfx = { de: \'\', en: \'_EN\', fr: \'_FR\', it: \'_IT\' }[lang] || \'\';\\nel.querySelectorAll(\'[data-cj-img]\').forEach(img => {\\n  const src = screen.files[img.getAttribute(\'data-cj-img\') + sfx + \'.png\'];\\n  if (src) img.src = src;\\n});\\nlet answerLockTs = null;\\n\\n// Select-then-confirm within one group. `onLock` fires on the\\n// second click of the same option, matching the original.\\nconst bindGroup = (root, onLock) => {\\n  const opts = Array.from(root.querySelectorAll(\'.kanji-opt\'));\\n  let locked = false;\\n  opts.forEach(opt => {\\n    opt.addEventListener(\'click\', () => {\\n      if (locked) return;\\n      if (opt.classList.contains(\'selected\')) {\\n        opt.classList.remove(\'selected\');\\n        opt.classList.add(\'locked\');\\n        locked = true;\\n        root.classList.add(\'is-locked\');\\n        onLock(opt);\\n      } else {\\n        opts.forEach(o => o.classList.remove(\'selected\'));\\n        opt.classList.add(\'selected\');\\n      }\\n    });\\n  });\\n};\\n\\nconst choices    = el.querySelector(\'#kanjiChoices\');\\nconst confidence = el.querySelector(\'#kanjiConfidence\');\\n\\nbindGroup(choices, (opt) => {\\n  const side = opt.getAttribute(\'data-side\');\\n  answerLockTs = performance.now();\\n  screen.data.chosen_side  = side;\\n  screen.data.chosen_img   = side === \'left\' ? screen.parameters.left_img : screen.parameters.right_img;\\n  screen.data.correct_side = screen.parameters.correct_side;\\n  screen.data.correct      = side === screen.parameters.correct_side ? 1 : 0;\\n  screen.data.rt_choice    = Math.round(answerLockTs - pageStart);\\n  confidence.hidden = false;\\n});\\n\\nbindGroup(confidence, (opt) => {\\n  const now = performance.now();\\n  screen.data.confidence        = parseInt(opt.getAttribute(\'data-cj\'), 10);\\n  screen.data.rt_confidence     = Math.round(now - pageStart);\\n  screen.data.rt_conf_from_choice = answerLockTs === null ? null : Math.round(now - answerLockTs);\\n  // The original waits 300 ms after the confidence lock before advancing.\\n  setTimeout(() => screen.respond(String(screen.data.confidence)), 300);\\n});\\n"}],"parameters":[],"id":"c14","plugins":[]},"c15":{"title":"Fixation","type":"lab.html.Screen","content":"<div class=\\"kanji-stage\\"><img class=\\"kanji-fix\\" src=\\"${ this.files[\'Fixationskreuz.jpg\'] }\\"></div>","timeout":"500","files":[{"localPath":"Fixationskreuz.jpg","poolPath":"embedded/977d7cc0d676ba2a9b5a1e8efd1fe04c80204001fd4fb6044352aec480532a88.jpg"},{"localPath":"Herbst_Kanji.jpg","poolPath":"embedded/f8be7e1abfc36cd9468311bbf925d67cc55102aed4db6d4b112835ff54ba04ce.jpg"},{"localPath":"Herbst.jpg","poolPath":"embedded/f6f99caeda6bfff6c149aebc40961a0af2dc272a6f56f14f0e43e112114fe353.jpg"},{"localPath":"Ast_Kanji.jpg","poolPath":"embedded/b0babd5be1a379342ae0043c1c9ab7e62e5004ac20df44a366aa1bf1057b6920.jpg"},{"localPath":"Ast.jpg","poolPath":"embedded/