nses":[],"messageHandlers":[],"parameters":[],"id":"c22","plugins":[]},"c23":{"title":"Learn A","type":"lab.flow.Loop","children":["c22"],"templateParameters":{"columns":[{"name":"list","type":"string"},{"name":"trial","type":"string"},{"name":"concept","type":"string"},{"name":"kanji_img","type":"string"},{"name":"meaning_img","type":"string"}],"rows":[["A","1","Herbst","Herbst_Kanji.jpg","Herbst.jpg"],["A","2","Ast","Ast_Kanji.jpg","Ast.jpg"],["A","3","Baumwolle","Baumwolle_Kanji.jpg","Baumwolle.jpg"]]},"shuffle":true,"files":[],"responses":[],"messageHandlers":[],"parameters":[],"id":"c23","plugins":[]},"c24":{"title":"Save learn_A","type":"lab.html.Screen","content":"<div class=\\"kanji-stage\\"><p class=\\"kanji-wait\\">…</p></div>","timeout":"50","messageHandlers":[{"message":"after:end","code":"if (!this.options.datastore || typeof labJSFields === \'undefined\') { return; }\\nconst extra = { block: \'learn_A\' };\\nconst qChoice = \'\';\\nconst qConf   = \'\';\\nif (qChoice) {\\n  const rows = (this.options.datastore.data || []).filter(\\n    r => r.sender === \'Recall trial\' && r.confidence !== undefined\\n  );\\n  const trials = rows.map((r, i) => {\\n    const t = { trial: i + 1, item: r.concept };\\n    t[\'Auswahl_\' + qChoice]               = r.chosen_img;\\n    t[\'Auswahl_\' + qConf]                 = r.confidence;\\n    t[\'Reaktionszeit_\' + qChoice + \'_ms\'] = r.rt_choice;\\n    t[\'Reaktionszeit_\' + qConf + \'_ms\']   = r.rt_confidence;\\n    t[\'Reaktionszeit_\' + qConf + \'_ab_\' + qChoice + \'_ms\'] = r.rt_conf_from_choice;\\n    t.korrekt       = r.correct;\\n    t.korrekt_seite = r.correct_side;\\n    t.gewaehlt      = r.chosen_side;\\n    t.orig_pos      = r.orig_pos;\\n    return t;\\n  });\\n  // One JSON column per block, plus the totals worth filtering on.\\n  extra[\'trials_\' + \'learn_A\'] = trials;\\n  extra[\'n_trials_\' + \'learn_A\']  = trials.length;\\n  extra[\'n_correct_\' + \'learn_A\'] = trials.filter(t => t.korrekt === 1).length;\\n}\\nif (!qChoice) {\\n  const lernSender = \'Learn A stimulus\';\\n  const lernRows = (this.options.datastore.data || []).filter(\\n    r => r.lern_item !== undefined && r.sender === lernSender\\n  );\\n  if (lernRows.length) {\\n    extra[\'trials_\' + \'learn_A\'] = lernRows.map((r, i) => ({\\n      trial: i + 1, item: r.lern_item,\\n      dauer_ms: (r.time_show === undefined || r.time_end === undefined)\\n        ? null : Math.round(r.time_end - r.time_show)\\n    }));\\n    extra[\'n_trials_\' + \'learn_A\'] = lernRows.length;\\n  }\\n}\\nconst dataStore = this.options.datastore;\\nextra.trigger_type       = \'finished\';\\nextra.labjs_response_id  = window.labjs_response_id;\\nextra.labjs_generated_id = labJSFields[\'labjs_generated_id\'];\\nif (labJSFields[\'extra_params\']) {\\n  for (const p in labJSFields[\'extra_params\']) {\\n    extra[\'extra_param_\' + p] = labJSFields[\'extra_params\'][p];\\n  }\\n}\\nextra.UserLanguage = (((document.querySelector(\'[class*=selfHelp-locale-]\') || {}).className || \'\')\\n  .match(/selfHelp-locale-([a-z]{2})/) || [])[1] || \'\';\\nextra.UserLanguage = extra.UserLanguage ? extra.UserLanguage.toUpperCase() : \'\';\\nconst redirectTo = (typeof resolveRedirectAtEnd === \'function\')\\n  ? resolveRedirectAtEnd(labJSFields[\'redirect_at_end\'], extra, labJSFields[\'base_path\'])\\n  : labJSFields[\'redirect_at_end\'];\\nconst go = () => {\\n  if (extra.trigger_type === \'finished\' && redirectTo) { window.location.href = redirectTo; }\\n};\\nPromise.resolve(dataStore.transmit(\'#\', extra)).then(go, go);\\n"}],"files":[],"responses":[],"parameters":[],"id":"c24","plugins":[]},"root":{"title":"Kanji Adults (seg1)","type":"lab.flow.Sequence","children":["c1","c2","c3","c4","c5","c6","c10","c11","c12","c13","c17","c18","c19","c23","c24"],"files":[],"responses":[],"messageHandlers":[],"parameters":[],"id":"root","plugins":[{"type":"lab.plugins.Metadata"}],"metadata":{"title":"kanji-adults-seg1","description":"Kanji Adults: paired-associate Kanji memory task","repository":"","contributors":""}}},"files":{"files":{"index.html":{"content":"data:text/html,%3C!doctype%20html%3E%0A%3Chtml%3E%0A%3Chead%3E%0A%20%20%3Cmeta%20charset%3D%22utf-8%22%3E%0A%20%20%3Ctitle%3EExperiment%3C%2Ftitle%3E%0A%20%20%3Cmeta%20name%3D%22viewport%22%20content%3D%22width%3Ddevice-width%2C%20initial-scale%3D1%22%3E%0A%20%20%24%7B%20header%20%7D%0A%3C%2Fhead%3E%0A%3Cbody%3E%0A%20%20%3Cdiv%20class%3D%22container%20fullscreen%22%20data-labjs-section%3D%22main%22%3E%0A%20%20%20%20%3Cmain%20class%3D%22content-vertical-center%20content-horizontal-center%22%3E%0A%20%20%20%20%20%20%3Cdiv%3E%3Ch2%3ELoading%20Experiment%3C%2Fh2%3E%3C%2Fdiv%3E%0A%20%20%20%20%3C%2Fmain%3E%0A%20%20%3C%2Fdiv%3E%0A%3C%2Fbody%3E%0A%3C%2Fhtml%3E%0A","source":"library"},"style.css":{"content":"data:text/css,%2F%2A%20Kanji%20Adults%20%E2%80%94%20lab.js%20task%20styling.%0A%0A%20%20%20Shipped%20by%20the%20%60kanji-task-style%60%20markdown%20section%2C%20which%20sits%20on%20the%20task%0A%20%20%20page%20ahead%20of%20the%20experiment%20and%20renders%20this%20file%20inside%20a%20%3Cstyle%3E%20tag.%0A%0A%20%20%20It%20cannot%20live%20anywhere%20inside%20the%20study%3A%20every%20lab.html.Screen%20does%0A%20%20%20%60el.innerHTML%20%3D%20content%60%20on%20run%2C%20so%20a%20%3Cstyle%3E%20in%20a%20screen%20is%20wiped%20by%20the%0A%20%20%20next%20one.%20Nor%20in%20the%20section%27s%20%60css%60%20field%20%E2%80%94%20that%20is%20a%20class-name%20list%0A%20%20%20rendered%20inside%20class%3D%22%E2%80%A6%22%2C%20so%20a%20stylesheet%20there%20never%20applies.%0A%0A%20%20%20Sizing%20note%3A%20the%20stimulus%20images%20are%202048x2048%2C%20so%20every%20image%20is%20bounded%0A%20%20%20here%20by%20viewport%20%2Aheight%2A%20first.%20Width-only%20limits%20%28e.g.%20max-width%3A%2045%25%29%0A%20%20%20let%20a%20square%20image%20grow%20as%20tall%20as%20it%20is%20wide%20and%20push%20the%20options%20below%0A%20%20%20the%20fold%20on%20a%20laptop%20screen.%20%2A%2F%0A%0A%2F%2A%20Full-bleed%20task.%0A%20%20%20The%20labJS%20style%20wraps%20the%20experiment%20in%20%60.container.fullscreen%60%2C%20which%20the%0A%20%20%20plugin%27s%20own%20lab.css%20gives%20a%2024px%20margin%2C%20a%201px%20border%2C%20a%20rounded%20corner%20and%0A%20%20%20a%20900px%20width%20variable%2C%20and%20pads%20%60main%60%20by%20another%2024px.%20For%20a%20timed%20task%0A%20%20%20that%20chrome%20is%20only%20wasted%20viewport%2C%20so%20the%20page%20overrides%20it%20here%20rather%0A%20%20%20than%20by%20patching%20the%20lab%20plugin.%20%2A%2F%0A.selfHelp-lab-js-holder%20%7B%0A%20%20width%3A%20100%25%3B%0A%20%20margin%3A%200%3B%0A%20%20padding%3A%200%3B%0A%7D%0A.selfHelp-lab-js-holder%20.container%2C%0A.selfHelp-lab-js-holder%20.container.fullscreen%20%7B%0A%20%20margin%3A%200%3B%0A%20%20padding%3A%200%3B%0A%20%20width%3A%20100%25%3B%0A%20%20max-width%3A%20none%3B%0A%20%20min-height%3A%20100vh%3B%0A%20%20border%3A%20none%3B%0A%20%20border-radius%3A%200%3B%0A%7D%0A.selfHelp-lab-js-holder%20main%2C%0A.selfHelp-lab-js-holder%20header%2C%0A.selfHelp-lab-js-holder%20footer%20%7B%0A%20%20padding%3A%200%3B%0A%20%20border%3A%20none%3B%0A%7D%0A%0A.kanji-stage%20%7B%0A%20%20display%3A%20flex%3B%0A%20%20flex-direction%3A%20column%3B%0A%20%20align-items%3A%20center%3B%0A%20%20justify-content%3A%20center%3B%0A%20%20%2F%2A%20The%20container%20chrome%20is%20stripped%20above%2C%20so%20the%20stage%20is%20the%20viewport.%20%2A%2F%0A%20%20min-height%3A%20100vh%3B%0A%20%20box-sizing%3A%20border-box%3B%0A%20%20padding%3A%201vh%201vw%3B%0A%20%20gap%3A%203vh%3B%0A%20%20overflow%3A%20hidden%3B%0A%7D%0A%0A%2F%2A%20Fixation%20cross%20%E2%80%94%20centred%2C%20and%20large%20enough%20to%20actually%20hold%20the%20eye.%0A%20%20%20Sized%20against%20the%20stimulus%20that%20follows%20%28max-height%3A%2068vh%29%2C%20not%20as%20an%0A%20%20%20afterthought%3A%20the%20cross%20marks%20the%20spot%20the%20kanji%20is%20about%20to%20occupy.%0A%0A%20%20%20The%20asset%20used%20to%20be%20an%2080px%20cross%20floating%20in%20a%201280x720%20white%20frame%2C%20so%0A%20%20%20only%206%25%20of%20the%20width%20was%20ink%20%E2%80%94%20every%20CSS%20width%20here%20was%20effectively%20divided%0A%20%20%20by%20sixteen%2C%20which%20is%20why%20earlier%20attempts%20to%20enlarge%20it%20did%20nothing%20visible.%0A%20%20%20It%20is%20now%20cropped%20square%20to%20the%20cross%2C%20so%20this%20width%20is%20the%20cross.%20%2A%2F%0A.kanji-fix%20%7B%20width%3A%20clamp%2880px%2C%2012vh%2C%20160px%29%3B%20height%3A%20auto%3B%20%7D%0A%0A%2F%2A%20Learning%20trial%3A%20kanji%20and%20meaning%20side%20by%20side.%0A%20%20%20Matches%20the%20Qualtrics%20LA2%20layout%2C%20but%20capped%20by%20height%20so%20the%20pair%20always%0A%20%20%20fits%20on%20one%20screen.%20%2A%2F%0A.kanji-pair%20%7B%0A%20%20flex-direction%3A%20row%3B%0A%20%20flex-wrap%3A%20nowrap%3B%0A%20%20gap%3A%204vw%3B%0A%7D%0A.kanji-pair%20.kanji-item%20%7B%0A%20%20max-height%3A%2068vh%3B%0A%20%20max-width%3A%2044vw%3B%0A%20%20width%3A%20auto%3B%0A%20%20height%3A%20auto%3B%0A%20%20object-fit%3A%20contain%3B%0A%7D%0A%0A%2F%2A%20Recall%20trial%3A%20cue%2C%20the%20two%20options%2C%20and%20the%20confidence%20row%20all%20share%20one%0A%20%20%20screen%20%28as%20in%20the%20Qualtrics%20original%29%2C%20so%20each%20band%20gets%20a%20smaller%20slice.%20%2A%2F%0A.kanji-cue%20%7B%0A%20%20max-height%3A%2024vh%3B%0A%20%20max-width%3A%2028vw%3B%0A%20%20width%3A%20auto%3B%0A%20%20height%3A%20auto%3B%0A%20%20object-fit%3A%20contain%3B%0A%7D%0A%0A.kanji-choices%20%7B%0A%20%20display%3A%20flex%3B%0A%20%20align-items%3A%20center%3B%0A%20%20justify-content%3A%20center%3B%0A%20%20gap%3A%205vw%3B%0A%20%20flex-wrap%3A%20nowrap%3B%0A%7D%0A%0A.kanji-opt%20%7B%0A%20%20border%3A%202px%20solid%20%23000%3B%0A%20%20border-radius%3A%2012px%3B%0A%20%20background%3A%20%23fff%3B%0A%20%20padding%3A%206px%3B%0A%20%20cursor%3A%20pointer%3B%0A%20%20transition%3A%20border-color%20.2s%20ease%2C%20transform%20.1s%20ease%3B%0A%20%20line-height%3A%200%3B%0A%7D%0A.kanji-opt%20img%20%7B%0A%20%20