-- Hide the floating CMS box on the questionnaire pages.
SET @box_css = '<style>\n/* Inline by necessity, not by preference. A section `css` field puts classes\n   on that section\'s own element, so neither of these can be a utility:\n   `.cms-edit` is a core element outside every section, and `body` is the page\n   itself - which `styles.min.css` paints `#fff!important`, so only\n   `!important` wins it back. Everything else is a utility on its section. */\n.cms-edit { display: none; }\n\nhtml, body { background-color: #eff8f5 !important; }\n</style>';
INSERT IGNORE INTO `sections` (`id_styles`, `name`, `owner`)
    VALUES (get_style_id('markdown'), 'kanji-box-style-welcome', NULL);
SET @kb_style_welcome = (SELECT id FROM sections WHERE name = 'kanji-box-style-welcome');
INSERT IGNORE INTO `pages_sections` (`id_pages`, `id_sections`, `position`)
VALUES (@kanji_welcome, @kb_style_welcome, 0);
